import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Button from '../components/Button';

export default function TasksPage() {
  const navigate = useNavigate();
  const [tasks, setTasks] = useState([]);
  const [tasksCopied, setTasksCopied] = useState(false);

  const currentDay = parseInt(localStorage.getItem("currentDay") || "1");
  const roadmapPlan = JSON.parse(localStorage.getItem("roadmapPlan") || "[]");

  useEffect(() => {
    if (!tasksCopied) {
      const carry = JSON.parse(localStorage.getItem("carryForward") || "[]");

      const allTasks = roadmapPlan.flat();
      const startIdx = (currentDay - 1) * 4;
      const todayTasks = allTasks.slice(startIdx, startIdx + 4);

      const combined = [
        ...carry.map((t, i) => ({
          id: i + 1,
          label: t,
          done: false,
          isCarriedOver: true
        })),
        ...todayTasks.map((t, i) => ({
          id: carry.length + i + 1,
          label: t,
          done: false,
          isCarriedOver: false
        }))
      ];

      setTasks(combined);
      setTasksCopied(true);
    }
  }, [tasksCopied, currentDay]);

  const toggleTask = (id) => {
    setTasks(tasks.map(t =>
      t.id === id ? { ...t, done: !t.done } : t
    ));
  };

  const handleSaveProgress = () => {
    const completed = tasks.filter(t => t.done).length;
    const remaining = tasks.filter(t => !t.done).map(t => t.label);

    localStorage.setItem("carryForward", JSON.stringify(remaining));
    localStorage.setItem("currentDay", currentDay + 1);

    const completedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");
    if (!completedDays.includes(currentDay)) completedDays.push(currentDay);

    localStorage.setItem("completedDays", JSON.stringify(completedDays));

    // XP
    const prevXP = parseInt(localStorage.getItem("xp") || "0");
    const taskXP = completed * 10;
    const bonusXP = remaining.length === 0 ? 20 : 0;
    localStorage.setItem("xp", prevXP + taskXP + bonusXP);

    localStorage.setItem("lastCompletedCount", completed);
    localStorage.setItem("lastTotalTasks", tasks.length);

    alert("Progress saved!");
    setTasksCopied(false);
    navigate("/tasks");
  };

  return (
    <div className="space-y-6">

      <h2 className="text-2xl font-semibold">Day {currentDay} Tasks</h2>

      {tasks.map(task => (
        <button
          key={task.id}
          onClick={() => toggleTask(task.id)}
          className={`block w-full p-4 border rounded-lg ${
            task.done ? "bg-green-100" : "bg-white"
          }`}
        >
          {task.label}
        </button>
      ))}

      <Button onClick={handleSaveProgress}>Save Progress</Button>

      {/* ✅ NEW BUTTON */}
      <Button
        onClick={() => navigate('/quiz-options')}
        className="bg-purple-500 text-white"
      >
        🧠 Take a Quiz
      </Button>

    </div>
  );
}
